INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (22,1,'<p>Это демонстрационный сайт Energine Simple. Администратор входит по ссылке «Вход» вверху страницы.</p>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (22,2,'<p>Це демонстраційний сайт Energine Simple. Адміністратор входить за посиланням «Вхід» угорі сторінки.</p>');
