INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (58,1,'<p> Для восстановления пароля укажите электронный адрес, указанный Вами\nпри регистрации.</p> <p>На него будет выслан автоматически созданный\nпароль.</p>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (59,1,'<h1>Добро пожаловать!</h1>\n<p>Это демонстрационный сайт Energine Simple — компактного ядра системы управления сайтом: дерево разделов, тексты, файлы, пользователи и права, переводы.</p>\n<ul>\n<li>Несколько языков: переводятся и страницы, и подписи интерфейса.</li>\n<li>Права: у каждой группы пользователей свои права на каждый раздел.</li>\n<li>Тексты правятся прямо на странице, в визуальном редакторе.</li>\n<li>Файлы хранятся в репозитории сайта и используются в текстах.</li>\n<li>Структура сайта — дерево разделов, которое меняется в админке.</li>\n</ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (59,2,'<h1>Вітаємо!</h1>\n<p>Це демонстраційний сайт Energine Simple — компактного ядра системи керування сайтом: дерево розділів, тексти, файли, користувачі й права, переклади.</p>\n<ul>\n<li>Кілька мов: перекладаються і сторінки, і підписи інтерфейсу.</li>\n<li>Права: у кожної групи користувачів свої права на кожен розділ.</li>\n<li>Тексти редагуються просто на сторінці, у візуальному редакторі.</li>\n<li>Файли зберігаються в репозиторії сайту й використовуються в текстах.</li>\n<li>Структура сайту — дерево розділів, яке змінюється в адмінці.</li>\n</ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (60,1,'<p>Energine Simple ставится одной командой установщика в пустую базу MySQL или MariaDB. Подробная инструкция — <b>docs/INSTALL.md</b> в репозитории.</p>\n<p><b>Что нужно:</b> PHP 8.5 с расширениями pdo_mysql, dom, xsl, simplexml, mbstring, gd, openssl и fileinfo; MySQL или MariaDB; веб-сервер, который отдаёт файлы как есть, а остальные адреса передаёт <b>index.php</b>.</p>\n<ol>\n<li>Положить репозиторий вне корня сайта (например, в <b>private/energine</b>), а в корень сайта скопировать точку входа из <b>htdocs</b>: <b>index.php</b>, <b>bootstrap.php</b>, <b>auth.php</b>, а также <b>resizer</b> и <b>uploads</b>.</li>\n<li>Поставить зависимости: <b>composer install --no-dev</b>.</li>\n<li>Запустить установку из корня сайта: <b>php index.php setup install --domain=example.org --db-name=… --db-user=… --admin-email=…</b>. Пароли базы и администратора установщик спросит сам. Он запишет конфиг сайта, поставит схему и базовые данные, создаст администратора и разложит статику.</li>\n<li>Настроить веб-сервер: адреса, которым не соответствует файл, — на <b>index.php</b> (для nginx: <b>try_files $uri $uri/ @rewrites</b> и <b>rewrite ^ /index.php last</b>), адреса превью <b>resizer/wШИРИНА-hВЫСОТА/путь</b> — на <b>resizer/timthumb.php</b>.</li>\n</ol>\n<p>После установки сайт пуст: главная, вход, регистрация, восстановление пароля и админка. Демо-контент, как на этом сайте, ставит команда <b>php index.php setup demo</b> — только на свежую установку.</p>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (61,1,'<p>Сайт состоит из разделов; у каждого раздела есть шаблон разметки и набор компонентов. Тексты правятся прямо на странице: администратор включает режим редактирования и меняет содержимое без отдельной формы.</p>\n  \n  <h3>Посмотреть</h3><ul><li><a href=\"/\">Главная страница</a> — текстовые блоки</li><li><a href=\"/sitemap/\">Карта сайта</a> — всё дерево разделов</li></ul>\n  <h3>В админке</h3><ul><li><a href=\"/admin/structure/\">Управление структурой</a></li></ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (61,2,'<p>Сайт складається з розділів; у кожного є шаблон розмітки та набір компонентів. Тексти правляться просто на сторінці: адміністратор вмикає режим редагування та змінює вміст без окремої форми.</p>\n  \n  <h3>Подивитися</h3><ul><li><a href=\"/ua/\">Головна сторінка</a></li><li><a href=\"/ua/sitemap/\">Карта сайту</a></li></ul>\n  <h3>В адмінці</h3><ul><li><a href=\"/ua/admin/structure/\">Керування структурою</a></li></ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (70,1,'<p>Пользователи объединяются в группы, у группы свои права на каждый раздел: без доступа, чтение, изменение, полный доступ. Есть регистрация, восстановление пароля и профиль.</p>\n  <p>Демо-пользователь: <b>olena@example.com</b> / <b>demo</b>.</p>\n  <h3>Посмотреть</h3><ul><li><a href=\"/register/\">Регистрация</a></li><li><a href=\"/profile/\">Профиль</a> — после входа</li></ul>\n  <h3>В админке</h3><ul><li><a href=\"/admin/users/\">Пользователи</a></li><li><a href=\"/admin/users/roles/\">Роли и права</a></li></ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (70,2,'<p>Користувачі об’єднуються в групи, у групи свої права на кожен розділ: без доступу, читання, зміна, повний доступ. Є реєстрація, відновлення пароля та профіль.</p>\n  <p>Демо-користувач: <b>olena@example.com</b> / <b>demo</b>.</p>\n  <h3>Подивитися</h3><ul><li><a href=\"/ua/register/\">Реєстрація</a></li></ul>\n  <h3>В адмінці</h3><ul><li><a href=\"/ua/admin/users/\">Користувачі</a></li></ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (71,1,'<p>Сайт двуязычный: русский и украинский. Переводится и содержимое, и подписи интерфейса. Язык по умолчанию идёт без префикса в адресе, остальные — с префиксом.</p>\n  <h3>Посмотреть</h3><ul><li><a href=\"/ua/features/\">Возможности по-украински</a></li></ul>\n  <h3>В админке</h3><ul><li><a href=\"/admin/translations/\">Переводы интерфейса</a></li><li><a href=\"/admin/translations/languages/\">Языки</a></li></ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (71,2,'<p>Сайт двомовний: російська та українська. Перекладається і вміст, і підписи інтерфейсу. Мова за замовчуванням іде без префікса в адресі.</p>\n  <h3>В адмінці</h3><ul><li><a href=\"/ua/admin/translations/\">Переклади інтерфейсу</a></li></ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (72,1,'<p>Человекопонятные адреса, отдельные заголовок, ключевые слова и описание для каждой страницы и языка, настройка индексации, карта сайта для поисковиков и robots.</p>\n  <p>Особенность хоста: файл robots.txt отдаёт веб-сервер, поэтому компонент доступен по адресу со слешем.</p>\n  <h3>Посмотреть</h3><ul><li><a href=\"/google-sitemap/\">Карта сайта для поисковиков</a></li><li><a href=\"/robots.txt/\">robots от движка</a></li><li><a href=\"/sitemap/\">Карта сайта для людей</a></li></ul>\n  <h3>В админке</h3><p>Метаданные страницы правятся в свойствах раздела в <a href=\"/admin/structure/\">редакторе структуры</a>.</p>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (72,2,'<p>Зрозумілі адреси, окремі заголовок, ключові слова й опис для кожної сторінки та мови, налаштування індексації, карта сайту для пошуковиків і robots.</p>\n  <h3>Подивитися</h3><ul><li><a href=\"/ua/sitemap/\">Карта сайту</a></li></ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (73,1,'<p>Разделы админки собраны на <a href=\"/admin/\">одной странице</a>; вход — по ссылке «Вход» вверху страницы.</p>\n<p>Кроме редакторов содержимого есть журнал действий и настройки сайта: название, описание и параметры для поисковых систем.</p>\n<h3>В админке</h3><ul><li><a href=\"/admin/action-log/\">Журнал действий</a></li><li><a href=\"/admin/settings/\">Настройки сайта</a></li></ul>');
INSERT INTO `share_textblocks_translation` (`tb_id`, `lang_id`, `tb_content`) VALUES (73,2,'<p>Розділи адмінки зібрані на <a href=\"/ua/admin/\">одній сторінці</a>; вхід — за посиланням «Вхід» угорі сторінки.</p>\n<h3>В адмінці</h3><ul><li><a href=\"/ua/admin/action-log/\">Журнал дій</a></li><li><a href=\"/ua/admin/settings/\">Налаштування сайту</a></li></ul>');
